define("tiny_omeroembed/ui", ["exports", "editor_tiny/options", "core/config", "tiny_omeroembed/modal", "core/modal_events"], function(exports, Options, ConfigModule, ModalModule, ModalEventsModule) {
    "use strict";
    Object.defineProperty(exports, "__esModule", {value: true});

    // Same non-.default resolution as before - core/config and
    // core/modal_events both end with an explicit `return`.
    var Config = ConfigModule;
    var Modal = ModalModule;
    var ModalEvents = ModalEventsModule;

    var MESSAGE_TYPE = "omero-embed-html";
    var READY_MESSAGE_TYPE = "omero-embed-ready";
    var WRITEUP_MESSAGE_TYPE = "omero-embed-existing-writeup";

    function readExistingEmbed(node) {
        var iframe = node.querySelector("iframe");
        if (!iframe) {
            return null;
        }

        var url;
        try {
            url = new URL(iframe.getAttribute("src"), window.location.href);
        } catch (e) {
            return null;
        }

        var pathParts = url.pathname.split("/");
        var proxyIndex = pathParts.indexOf("proxy.php");
        if (proxyIndex === -1 || !pathParts[proxyIndex + 2]) {
            return null;
        }
        var subject = decodeURIComponent(pathParts[proxyIndex + 2]);

        var table = node.querySelector("table");
        var layout = "imageonly";
        var writeupHtml = null;
        if (table) {
            var cells = Array.prototype.slice.call(table.querySelectorAll("tr > td"));
            var iframeCellIndex = -1;
            var writeupCell = null;
            for (var i = 0; i < cells.length; i++) {
                if (cells[i].querySelector("iframe")) {
                    if (iframeCellIndex === -1) {
                        iframeCellIndex = i;
                    }
                } else if (!writeupCell) {
                    writeupCell = cells[i];
                }
            }
            layout = iframeCellIndex === 0 ? "slideleft" : "slideright";
            if (writeupCell) {
                writeupHtml = writeupCell.innerHTML;
            }
        }

        return {
            params: {
                subject: subject,
                images: url.searchParams.get("images") || "",
                dataset: url.searchParams.get("dataset") || "",
                browsable: url.searchParams.has("browsable"),
                layout: layout,
                width: node.style.maxWidth || "",
                height: iframe.style.height || "",
            },
            writeupHtml: writeupHtml,
        };
    }

    function escapeEnclosingTable(editor) {
        var outerTable = null;
        var table = editor.selection.getNode().closest("table");
        while (table) {
            outerTable = table;
            table = table.parentNode ? table.parentNode.closest("table") : null;
        }
        if (outerTable) {
            editor.selection.select(outerTable);
            editor.selection.collapse(false);
        }
    }

    exports.handleAction = function(editor) {
        var contextId = Options.getContextId(editor);
        var existingNode = editor.selection.getNode().closest("[data-omero-embed]");
        var existing = existingNode ? readExistingEmbed(existingNode) : null;
        if (!existingNode) {
            escapeEnclosingTable(editor);
        }

        var iframeUrl = Config.wwwroot + "/local/omeroembed/author.php?contextid=" + contextId + "&embedded=1";
        if (existing) {
            var p = existing.params;
            iframeUrl += "&subject=" + encodeURIComponent(p.subject)
                + "&images=" + encodeURIComponent(p.images)
                + "&dataset=" + encodeURIComponent(p.dataset)
                + "&layout=" + encodeURIComponent(p.layout)
                + "&width=" + encodeURIComponent(p.width)
                + "&height=" + encodeURIComponent(p.height)
                + (p.browsable ? "&browsable=1" : "");
        }

        return Modal.create({
            templateContext: {iframeurl: iframeUrl},
        }).then(function(modal) {
            var messageListener = null;

            var cleanup = function() {
                if (messageListener) {
                    window.removeEventListener("message", messageListener);
                    messageListener = null;
                }
            };

            messageListener = function(event) {
                if (event.origin !== window.location.origin) {
                    return;
                }
                if (!event.data || !event.data.type) {
                    return;
                }

                if (event.data.type === READY_MESSAGE_TYPE) {
                    if (existing && existing.writeupHtml) {
                        var iframeEl = modal.getRoot()[0].querySelector("iframe");
                        if (iframeEl && iframeEl.contentWindow) {
                            iframeEl.contentWindow.postMessage(
                                {type: WRITEUP_MESSAGE_TYPE, html: existing.writeupHtml},
                                window.location.origin
                            );
                        }
                    }
                    return;
                }

                if (event.data.type === MESSAGE_TYPE) {
                    if (existingNode) {
                        editor.dom.setOuterHTML(existingNode, event.data.html);
                    } else {
                        editor.insertContent(event.data.html);
                    }
                    cleanup();
                    modal.destroy();
                }
            };
            window.addEventListener("message", messageListener);

            modal.getRoot().on(ModalEvents.hidden, cleanup);
        });
    };
});
